/**
 * Deterministic generator for data/audio/vitrifi.json — the ~1 hour
 * audio-optimized narration for /experience/vitrifi, sourced from the real
 * (now shut-down) Vitrifi "Cortex Portal" codebase.
 *
 * Hand-authored plain-prose chapters; this script does only the mechanical
 * math so the output is valid against the Rust audio-gate by construction:
 *   - per-chapter duration = estimate_secs(words)  (mirrors crates/ml wpm.rs)
 *   - cumulative start_secs, total duration, canonical full_script
 *
 * Run:  npx tsx scripts/build-vitrifi-audio.ts
 * Gate: pnpm audio:gate:check vitrifi
 *
 * Constraints honoured by the prose below (public/owner page, audio):
 *   - no secrets/tokens/internal hostnames, no individual coworkers named
 *   - carrier names (CityFibre, Openreach, BT) allowed
 *   - plain prose only (no markdown/code/pipes/links/visual refs/summary cliché)
 */

import fs from "fs";
import path from "path";

// Mirrors crates/ml/src/audio_guide/wpm.rs exactly (integer math, 150 wpm).
const NARRATION_WPM = 150;
function countWords(text: string): number {
  return text.trim().split(/\s+/).filter(Boolean).length;
}
function estimateSecs(words: number): number {
  if (words === 0) return 0;
  return Math.max(1, Math.floor((words * 60) / NARRATION_WPM));
}

