const built = chapters.map((c, index) => {
  const words = countWords(c.script);
  return {
    index,
    title: c.title,
    duration_secs: estimateSecs(words),
    script: c.script,
  };
});

let cursor = 0;
const withStarts = built.map((c) => {
  const start_secs = cursor;
  cursor += c.duration_secs;
  return {
    index: c.index,
    title: c.title,
    start_secs,
    duration_secs: c.duration_secs,
    script: c.script,
  };
});

const total = withStarts.reduce((s, c) => s + c.duration_secs, 0);
const fullScript = withStarts
  .map((c) => `## ${c.title}\n\n${c.script}`)
  .join("\n\n");

const meta = {
  slug: "vitrifi",
  title:
    "Vitrifi Cortex Portal: Multi-Tenant Wholesale Broadband Engineering — Audio Guide",
  voice: "pending-tts",
  duration_secs: total,
  file_size_bytes: 0,
  audio_url: "",
  chapters: withStarts,
  full_script: fullScript,
};

const outPath = path.join(process.cwd(), "data", "audio", "vitrifi.json");
fs.writeFileSync(outPath, JSON.stringify(meta, null, 2) + "\n", "utf-8");

const totalWords = withStarts.reduce((s, c) => s + countWords(c.script), 0);
console.log(
  `wrote ${outPath}\n` +
    `chapters=${withStarts.length} words=${totalWords} ` +
    `duration=${total}s (~${Math.round(total / 60)} min)`,
);
